def parse_verification(text: str) -> tuple[str, list[Func]]:
    modules = MODULE_RE.findall(text)
    verification = next(
        (
            module
            for module in modules
            if module.endswith("VERIFICATION")
            and not module.endswith("-SYNTAX")
